composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    pull_policy: build
    build:
      context: https://github.com/qdrant/mcp-server-qdrant.git#main
      dockerfile: Dockerfile
    container_name: {{containerName}}
    restart: unless-stopped
    ports:
      - "{{envRaw.QDRANT_MCP_PORT}}:{{envRaw.QDRANT_MCP_PORT}}"
    volumes:
      - /opt/appdata/qdrant-mcp/data:/data
    environment:
      FASTMCP_SERVER_HOST: "0.0.0.0"
      FASTMCP_SERVER_PORT: {{env.QDRANT_MCP_PORT}}
      QDRANT_URL: {{env.QDRANT_URL}}
      QDRANT_API_KEY: {{env.QDRANT_API_KEY}}
      COLLECTION_NAME: {{env.COLLECTION_NAME}}
      EMBEDDING_MODEL: {{env.EMBEDDING_MODEL}}
    command: ["--transport", "sse"]
